/* Keep original inputs as the source of truth for existing form handlers. */
(()=>{let popup=null,anchor=null;const enhanced=new WeakMap();
function close(focus=false){popup?.remove();popup=null;if(anchor){anchor.setAttribute('aria-expanded','false');if(focus)anchor.focus()}anchor=null}
function place(box,b){const r=b.getBoundingClientRect(),width=Math.min(innerWidth-24,Math.max(r.width,box.classList.contains('color-editor')?250:180));box.style.width=width+'px';box.style.left=Math.max(12,Math.min(r.left,innerWidth-width-12))+'px';const h=Math.min(box.scrollHeight,310);box.style.top=(innerHeight-r.bottom>h+12?r.bottom+5:Math.max(12,r.top-h-5))+'px'}
function show(box,b){close();popup=box;anchor=b;(b.closest('dialog[open]')||document.body).append(box);b.setAttribute('aria-expanded','true');place(box,b)}
function dispatch(input){input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}))}
function label(input){return input.getAttribute('aria-label')||document.querySelector(`label[for="${CSS.escape(input.id)}"]`)?.textContent||input.previousElementSibling?.textContent||'Выбрать'}
function select(input){if(input.multiple||input.size>1)return;const wrap=document.createElement('span');wrap.className='select-control';input.before(wrap);wrap.append(input);input.classList.add('native-control');input.tabIndex=-1;input.setAttribute('aria-hidden','true');const b=document.createElement('button');b.type='button';b.className='select-button';b.setAttribute('aria-haspopup','listbox');b.setAttribute('aria-expanded','false');wrap.append(b);const update=()=>{const text=input.selectedOptions[0]?.textContent||'Выбрать';b.replaceChildren();const name=document.createElement('span');name.textContent=text;const arrow=document.createElement('span');arrow.textContent='⌄';arrow.setAttribute('aria-hidden','true');b.append(name,arrow);b.disabled=input.disabled;b.setAttribute('aria-label',label(input)+': '+text)};enhanced.set(input,update);update();input.addEventListener('change',update);input.addEventListener('invalid',()=>b.focus());b.addEventListener('click',()=>{if(anchor===b){close();return}const box=document.createElement('div');box.className='control-popup';box.setAttribute('role','listbox');box.setAttribute('aria-label',label(input));for(const option of input.options){const item=document.createElement('button');item.type='button';item.className='control-option';item.setAttribute('role','option');item.setAttribute('aria-selected',String(option.selected));item.disabled=option.disabled;const name=document.createElement('span');name.textContent=option.textContent;item.append(name);if(option.selected){const check=document.createElement('span');check.textContent='✓';item.append(check)}item.onclick=()=>{input.value=option.value;close(true);dispatch(input)};box.append(item)}show(box,b);const selected=box.querySelector('[aria-selected=true]');(selected||box.querySelector('button:not(:disabled)'))?.focus();selected?.scrollIntoView({block:'nearest'});place(box,b)});b.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();b.click()}})}
function color(input){const b=document.createElement('button');b.type='button';b.className='color-button';b.setAttribute('aria-haspopup','dialog');b.setAttribute('aria-expanded','false');input.before(b);input.classList.add('native-control');input.tabIndex=-1;input.setAttribute('aria-hidden','true');const update=()=>{b.replaceChildren();const swatch=document.createElement('i');swatch.style.background=input.value;b.append(swatch);const text=document.createElement('span');text.textContent=input.value.toUpperCase();b.append(text);b.disabled=input.disabled;b.setAttribute('aria-label',label(input)+': '+input.value)};enhanced.set(input,update);update();input.addEventListener('input',update);input.addEventListener('change',update);b.onclick=()=>{if(anchor===b){close();return}const box=document.createElement('div');box.className='control-popup color-editor';box.setAttribute('role','dialog');box.setAttribute('aria-label','Цвет');const preview=document.createElement('div');preview.className='color-preview';box.append(preview);const hex=document.createElement('input');hex.type='text';hex.maxLength=7;hex.setAttribute('aria-label','HEX цвет');const sliders=[];const rgb=()=>[1,3,5].map(i=>parseInt(input.value.slice(i,i+2),16));function refresh(){preview.style.background=input.value;hex.value=input.value.toUpperCase();rgb().forEach((v,i)=>sliders[i].value=v)}function set(value){input.value=value;dispatch(input);if(input.isConnected)refresh();else close()}['Красный','Зелёный','Синий'].forEach((name,i)=>{const l=document.createElement('label');l.textContent=name;const slider=document.createElement('input');slider.type='range';slider.min='0';slider.max='255';slider.setAttribute('aria-label',name);sliders.push(slider);slider.oninput=()=>{const values=rgb();values[i]=Number(slider.value);set('#'+values.map(v=>v.toString(16).padStart(2,'0')).join(''))};l.append(slider);box.append(l)});hex.onchange=()=>{const value=hex.value.startsWith('#')?hex.value:'#'+hex.value;if(/^#[0-9a-f]{6}$/i.test(value))set(value);else refresh()};box.append(hex);const palette=document.createElement('div');palette.className='color-palette';['#000000','#ffffff','#ff5353','#ffc857','#8fd5ad','#67b4ff','#ac87ef','#ff91c0'].forEach(value=>{const item=document.createElement('button');item.type='button';item.style.background=value;item.setAttribute('aria-label',value);item.onclick=()=>set(value);palette.append(item)});box.append(palette);refresh();show(box,b);hex.focus()}}
function scan(){if(anchor&&!anchor.isConnected)close();document.querySelectorAll('select,input[type=color]').forEach(input=>{if(enhanced.has(input))return;if(input.tagName==='SELECT')select(input);else color(input)})}
let scheduled=false;new MutationObserver(records=>{for(const record of records){const input=record.target.closest?.('select,input[type=color]');if(input&&enhanced.has(input))enhanced.get(input)()}if(!scheduled){scheduled=true;queueMicrotask(()=>{scheduled=false;scan()})}}).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['disabled','value','selected']});
document.addEventListener('pointerdown',e=>{if(popup&&!popup.contains(e.target)&&!anchor?.contains(e.target))close()},true);document.addEventListener('keydown',e=>{if(!popup)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();close(true)}else if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)&&popup.getAttribute('role')==='listbox'){e.preventDefault();const options=[...popup.querySelectorAll('button:not(:disabled)')];const i=options.indexOf(document.activeElement);const n=e.key==='Home'?0:e.key==='End'?options.length-1:(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options[n]?.focus()}},true);document.addEventListener('scroll',e=>{if(popup&&!popup.contains(e.target))close()},true);window.addEventListener('resize',()=>close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',()=>close()));scan();
})();
